props:
className={headerOwnsDetail ? "mobile-header mobile-header-detail" : "mobile-header"} detail={headerOwnsDetail} contentHeader={headingPlacement==="content"} leadingClassName="mobile-header-leading" leading={<>
        {headerOwnsDetail ? !formActive&&<Link scroll={false} className="mobile-back" href={backHref!} aria-label={backLabel}><Icon name="back"/></Link> : pathname==="/dashboard" ? <Link href="/dashboard" className="mobile-header-brand" aria-label="Zur Übersicht"><Logo compact/><span>One</span></Link> : <h1 className="mobile-section-title"><LocalizedText verbatim={titleIsUserContent}>{title}</LocalizedText></h1>}
        {headerOwnsDetail&&<div className="mobile-header-context"><h1 className="mobile-header-title"><span><LocalizedText verbatim={titleIsUserContent}>{title}</LocalizedText></span></h1></div>}
      </>} actionClassName={headerOwnsDetail?"mobile-detail-actions":"mobile-header-actions"} actions={headerOwnsDetail ? (allowed&&(headerActions||mobileActions||headingActions)?<>{headerActions}{mobileActions??headingActions}</>:undefined) : <>
        {allowed&&(headerActions??mobileActions)}
        <IconButton label="Suche" icon="search" onClick={()=>setSheet("search")}/>
        <LocalizedElement as="button" className="mobile-notification-button icon-button" type="button" aria-label="Benachrichtigungen" onClick={openNotifications}><Icon name="bell"/>{unreadNotifications>0&&<i className="notification-badge"><LocalizedText>{unreadNotifications>99?"99+":unreadNotifications}</LocalizedText></i>}</LocalizedElement>
        <LocalizedElement as="button" className="avatar avatar-button" type="button" aria-label="Benutzerkonto" onClick={()=>setSheet("account")}><Avatar name={profile.name} identity={profile.identity} src={profile.avatar} size="small"/></LocalizedElement>
      </>}

as="button" ref={trigger} id={props.id??id+"-trigger"} type="button" role="combobox" disabled={props.disabled} aria-busy={props["aria-busy"]} className={[props.className,'form-control','app-select-trigger'].filter(Boolean).join(' ')} aria-label={props['aria-label']} aria-labelledby={props['aria-labelledby']} aria-describedby={[props['aria-describedby'],invalid?id+'-error':undefined].filter(Boolean).join(' ')||undefined} aria-required={props.required} aria-invalid={props['aria-invalid']??(invalid||undefined)} aria-haspopup="listbox" aria-expanded={open} aria-controls={open?id:undefined} aria-activedescendant={open?`${id}-${active}`:undefined} data-select-id={props.id} onClick={()=>{if(open)close();else show();}} onBlur={event=>{if(!(event.relatedTarget instanceof Node)||!popup.current?.contains(event.relatedTarget))close()}} onKeyDown={event=>{
  if(event.defaultPrevented||props.multiple)return;
  if(event.key==='Tab'){if(open&&search&&!event.shiftKey){event.preventDefault();searchInput.current?.focus();}else close();return;}
  if(event.key==='Escape'&&open){event.preventDefault();event.stopPropagation();close();return;}
  if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(event.key)){
   event.preventDefault();if(!open){show();if(event.key==='Home'||event.key==='End'){const indices=Array.from(control.current?.options??[]).map((option,index)=>available(option)?index:-1).filter(index=>index>=0);setActive(event.key==='Home'?indices[0]??0:indices.at(-1)??0);}return;}if(event.key==='Enter'||event.key===' '){choose(active);return;}
   const indices=options.map((_,i)=>i).filter(enabled),at=indices.indexOf(active);setActive(event.key==='Home'?indices[0]:event.key==='End'?indices.at(-1)!:indices[Math.max(0,Math.min(indices.length-1,at+(event.key==='ArrowDown'?1:-1)))]??active);
  }else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey&&!event.altKey){event.preventDefault();const now=Date.now();typeahead.current={text:(open&&now-typeahead.current.at<700?typeahead.current.text:'')+event.key.toLocaleLowerCase(),at:now};if(!open)show();const index=Array.from(control.current?.options??[]).findIndex(option=>available(option)&&option.text.toLocaleLowerCase().startsWith(typeahead.current.text));if(index>=0)setActive(index);}
 }}

